        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 or abs(dr) != abs(dc):
                continue

            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1

            # Connect the two 1s.
            r, c = r1, c1
            while True:
                out[r][c] = 1
                if (r, c) == (r2, c2):
                    break
                r += sr
                c += sc

            # A 6 on the connecting segment emits a perpendicular 6-line.
            for mr, mc in sixes:
                if (mr - r1) * dc != (mc - c1) * dr:
                    continue
                if not (min(r1, r2) <= mr <= max(r1, r2) and
                        min(c1, c2) <= mc <= max(c1, c2)):
                    continue

                # Perpendicular diagonal has step (1, -sc).
                for sign in (-1, 1):
                    r, c = mr, mc
                    while 0 <= r < h and 0 <= c < w:
                        if grid[r][c] != 1:
                            out[r][c] = 6
                        r += sign
                        c -= sign * sc

    return out
